body:
There is a high CPU usage potential issue in Netty when SSL is used. I was able to reproduce it only in NetBeans (I'm using v7.3) in both debug and run mode. The issue does not occurs when the program is run from the command prompt. However, this may be due the different speed in the execution.

The issue occurs when the client uploads binary data to the server and terminates the connection before the server can send all text responses back (it can probably happen in other configurations as well). At that point the server starts to use 100% of a CPU core probably due an infinite loop.

Although this may not be an actual bug since it is only reproducible in NetBeans I'm submitting it just in case. It is possible that the different speed in execution causes the problem to manifest. In addition it may not occur on each run. The program may have to be run a few times (usually two is enough).

This is a link to the complete project:
http://s000.tinyupload.com/index.php?file_id=86080272745977958666

Following is the code without a key store and some utility classes. Note that if "//Thread.sleep(2000);" is uncommented the client can read all responses the issue does not occur.

```
/**
 *
 * @author None
 */
public class Main {

    private static void startServer(final SSLContext sslContext) throws InterruptedException {
        ServerBootstrap b = new ServerBootstrap();
        try {
            b.group(new AioEventLoopGroup(), new AioEventLoopGroup())
                    .channel(AioServerSocketChannel.class)
                    .childHandler(new ChannelInitializer<SocketChannel>() {
                @Override
                public void initChannel(SocketChannel ch) throws Exception {
                    ChannelPipeline p = ch.pipeline();
                    SSLEngine engine = sslContext.createSSLEngine();
                    engine.setUseClientMode(false);
                    p.addLast("ssl", new SslHandler(engine));
                    p.addLast("encoder", new ObjectEncoder());
                    p.addLast("handler2", new ChannelInboundByteHandlerAdapter() {
                        @Override
                        protected void inboundBufferUpdated(ChannelHandlerContext ctx, ByteBuf in) throws Exception {
                            ctx.write(in.readableBytes() + " bytes received.");
                        }
                    });
                }
            });

            Channel channel = b.bind(12345).sync().channel();
            System.out.println("[Server] Started");
            // Bind and start to accept incoming connections.
            channel.closeFuture().sync();
            System.out.println("[Server] Stopped");
        } finally {
            b.shutdown();
        }
    }

    private static void startClient(final SSLContext sslContext) throws InterruptedException {
        Bootstrap b = new Bootstrap();
        try {
            b.option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 30000)
                    .group(new OioEventLoopGroup())
                    .channel(OioSocketChannel.class)
                    .handler(new ChannelInitializer<SocketChannel>() {
                @Override
                protected void initChannel(SocketChannel ch) throws Exception {
                    ChannelPipeline p = ch.pipeline();
                    SSLEngine engine = sslContext.createSSLEngine();
                    engine.setUseClientMode(true);
                    p.addLast("ssl", new SslHandler(engine));
                    p.addLast("decoder", new ObjectDecoder(ClassResolvers.softCachingConcurrentResolver(null)));
                    p.addLast("handler1", new ChannelInboundMessageHandlerAdapter<String>() {
                        @Override
                        public void messageReceived(ChannelHandlerContext ctx, String msg) throws Exception {
                            System.out.println("Server said: " + msg);
                        }
                    });
                }
            });
            Channel channel = b.connect("localhost", 12345).sync().channel();
            System.out.println("[Client] Connected to server.");
            ByteBuf buffer = Unpooled.buffer(1024 * 1024);
            buffer.writeZero(buffer.capacity());
            channel.write(buffer);
            channel.flush().sync();
            //Thread.sleep(2000);
            channel.close().sync();
            System.out.println("[Client] Exit");
        } finally {
            b.shutdown();
        }
    }

    /**
     * @param args the command line arguments
     */
    public static void main(String[] args) throws Exception {
        //System.setProperty("javax.net.debug", "ssl");
        KeyStoreSettings keyStoreSettings = new KeyStoreSettings(
                "/keystore-test.jks",
                "....",
                "JKS");
        KeyStoreSettings trustStoreSettings = new KeyStoreSettings(
                "/keystore-test.jks",
                "....",
                "JKS");
        final SSLContext sslContext = SecurityUtils.createSSLContext(
                keyStoreSettings,
                "....",
                trustStoreSettings);

        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    startServer(sslContext);
                } catch (InterruptedException ex) {
                }
            }
        }).start();
        Thread.sleep(1000);
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    startClient(sslContext);
                } catch (InterruptedException ex) {
                }
            }
        }).start();
        System.out.println("MAIN: Server and client started.");

        if (System.console() != null) {
            System.console().readLine();
        } else {
            new BufferedReader(new InputStreamReader(System.in)).readLine();
        }
    }
}
